SELECT product_id, product_name, sku, current_stock, safety_stock, nearest_expiry_date
FROM agent_v3_product_inventory_view WHERE agent_v3_product_inventory_view.store_id = ANY(:allowedStoreIds) ORDER BY current_stock ASC
LIMIT 10;

SELECT project_id, project_name, price, duration
FROM agent_v3_project_catalog_view
WHERE agent_v3_project_catalog_view.store_id = ANY(:allowedStoreIds) AND (project_id = 81) LIMIT 100;

SELECT COUNT(DISTINCT staff_id) AS staff_count
FROM agent_v3_staff_profile_view
WHERE agent_v3_staff_profile_view.store_id = ANY(:allowedStoreIds) AND (status = '***') LIMIT 1;

SELECT staff_id, staff_name, level_name
FROM agent_v3_staff_profile_view
WHERE agent_v3_staff_profile_view.store_id = ANY(:allowedStoreIds) AND (staff_id = 41) LIMIT 100;

SELECT staff_id, staff_name, level_name
FROM agent_v3_staff_profile_view
WHERE agent_v3_staff_profile_view.store_id = ANY(:allowedStoreIds) AND (staff_id = 43) LIMIT 100;

SELECT staff_id, staff_name, level_name
FROM agent_v3_staff_profile_view
WHERE agent_v3_staff_profile_view.store_id = ANY(:allowedStoreIds) AND (staff_id = 40) LIMIT 100;

SELECT level_name, COUNT(DISTINCT staff_id) AS staff_count
FROM agent_v3_staff_profile_view WHERE agent_v3_staff_profile_view.store_id = ANY(:allowedStoreIds) GROUP BY level_name
LIMIT 100;

SELECT staff_id, staff_name, created_at
FROM agent_v3_staff_profile_view WHERE agent_v3_staff_profile_view.store_id = ANY(:allowedStoreIds) ORDER BY created_at DESC
LIMIT 10;

SELECT level_name
FROM agent_v3_staff_profile_view WHERE agent_v3_staff_profile_view.store_id = ANY(:allowedStoreIds) GROUP BY level_name
LIMIT 100;

SELECT customer_id, customer_name_masked, days_since_last_visit, average_return_interval_days, customer_status
FROM ask_data_customer_profile_summary_view
WHERE ask_data_customer_profile_summary_view.store_id = ANY(:allowedStoreIds) AND (days_since_last_visit > average_return_interval_days * 1.5) LIMIT 100;
